        public Canonical()
        {
            // index of the permutation
            _permutation = -1;
        }

        public void SetIndex(int[] board)
        {
            _permutation = 0;
            for (var p = 1; p < _canonicalToIndex.GetLength(0); p++)
            {
                for (var k = 0; k < 80; k++)
                {
                    var candidate = board[_canonicalToIndex[p, k]];
                    var best = board[_canonicalToIndex[_permutation, k]];
                    if (candidate < best)
                    {
                        _permutation = p;
                        break;
                    }

                    if (candidate > best)
                    {
                        break;
                    }
                }
            }
        }

        public void SetIndex(VolcanoGame game)
        {
            SetIndex(game.CurrentState);
        }

        public void SetIndex(Board board)
        {
            SetIndex(board.Tiles);
        }

        private void VerifyIndex()
        {
            if (_permutation == -1)
            {
                throw new Exception("Must specify which index was used to canonicalize.");
            }
        }

        public int BoardToCanonical(int index)
        {
            VerifyIndex();

            if (index < 0 || index >= 80)
            {
                return index;
            }

            return _indexToCanonical[_permutation, index];
        }

        public int CanonicalToBoard(int index)
        {
            VerifyIndex();

            if (index < 0 || index >= 80)
            {
                return index;
            }

            return _canonicalToIndex[_permutation, index];
        }

        public int[] Canonicalize(int[] board)
        {
            var newBoard = new int[board.Length];
            for (var i = 0; i < 80; i++)
            {
                newBoard[BoardToCanonical(i)] = board[i];
            }

            return newBoard;
        }

        public bool[] Canonicalize(bool[] board)
        {
            var newBoard = new bool[board.Length];
            for (var i = 0; i < 80; i++)
            {
                newBoard[BoardToCanonical(i)] = board[i];
            }

            return newBoard;
        }

        public Board Canonicalize(Board board)
        {
            var newBoard = new Board(board)
            {
                Tiles = Canonicalize(board.Tiles),
                Dormant = Canonicalize(board.Dormant),
            };

            return newBoard;
        }

        public int[] Decanonicalize(int[] board)
        {
            var newBoard = new int[board.Length];
            for (var i = 0; i < 80; i++)
            {
                newBoard[CanonicalToBoard(i)] = board[i];
            }

            return newBoard;
        }

